"""Condition-aware overview of health approaches, with original government sources.

An approach label is not a blanket endorsement: effectiveness and safety depend
on the exact intervention, condition, practitioner, and patient.
"""
import streamlit as st

ROWS = [
    ("🩺 Evidence-based conventional medicine", "Diagnosis, proven treatments, screening, medicines and procedures can prevent serious harm.", "Side effects, cost and access vary; treatment choices need shared decision-making.", "Strong for specific validated interventions; varies by condition.", "Symptoms needing diagnosis, acute or serious illness, and management of diagnosed conditions.", "Use qualified clinicians; ask about benefits, harms and alternatives.", "https://medlineplus.gov/healthtopics.html"),
    ("🌱 Preventive and lifestyle medicine", "Diet, activity, sleep and risk-factor care can reduce chronic disease risk.", "Takes sustained effort; cannot replace indicated medicines or urgent care.", "Strong for many preventive behaviors; outcomes vary by goal.", "Ongoing prevention and alongside treatment for cardiometabolic risk.", "Set a practical habit and track relevant outcomes with your clinician.", "https://www.cdc.gov/chronic-disease/prevention/index.html"),
    ("🚶 Rehabilitation and physical therapy", "Task practice, movement and conditioning can improve function after illness or injury.", "Needs an individualized plan and follow-through; some exercises require precautions.", "Established in many indications; program and dose depend on condition.", "After stroke, injury, surgery, falls or persistent movement limitation when appropriate.", "Ask for a licensed therapist and a measurable function goal.", "https://www.ninds.nih.gov/health-information/stroke/recovery"),
    ("🧠 Psychological and behavioral therapies", "Structured skills such as CBT can address distress, coping and behavior.", "Requires time and therapeutic fit; severe symptoms may need combined or urgent care.", "Established for several specific mental health conditions; varies by therapy.", "When anxiety, depression, sleep or behavior problems impair daily life.", "Seek a qualified mental health professional and a condition-matched therapy.", "https://www.nimh.nih.gov/health/topics/psychotherapies"),
    ("☯️ Traditional Chinese medicine (TCM)", "Some components, such as acupuncture or tai chi, may help certain pain or balance outcomes.", "Herbal mixtures can interact with drugs or contain contaminants; broad disease claims often lack good evidence.", "Mixed and intervention-specific; do not generalize across all TCM.", "Consider a specific, supported practice as an adjunct for a relevant symptom.", "Check practitioner safety and discuss herbs with the treating clinician.", "https://www.nccih.nih.gov/health/traditional-chinese-medicine-what-you-need-to-know"),
    ("🌿 Ayurveda", "Familiar food and routine practices may support an enjoyable, sustainable lifestyle.", "Clinical claims often lack rigorous support; some preparations contain toxic metals or interact with drugs.", "Limited for treating disease; evaluate each practice separately.", "Use safe culinary traditions for preference, alongside appropriate care.", "Avoid unverified medicinal products; disclose all preparations to clinician.", "https://www.nccih.nih.gov/health/ayurvedic-medicine-in-depth"),
    ("🧘 Yoga and meditation", "May help stress, well-being, flexibility and selected pain outcomes.", "Effects vary; poses and intensive practice need adaptations for some conditions.", "Moderate or limited depending on outcome; useful adjunct in selected settings.", "For stress management or gentle activity when physically suitable.", "Start at an appropriate level; adapt for injury, pregnancy or mobility concerns.", "https://www.nccih.nih.gov/health/yoga-effectiveness-and-safety"),
    ("💆 Massage and manual therapies", "May offer short-term relief for some pain and relaxation.", "Benefits may be temporary; forceful manipulation can carry condition-specific risks.", "Limited to moderate for selected symptoms, depending on technique.", "Consider for symptom relief after a diagnosis and safety check.", "Choose a trained practitioner; disclose injury, blood thinners and bone fragility.", "https://www.nccih.nih.gov/health/chronic-pain-and-complementary-health-approaches-usefulness-and-safety"),
    ("🔎 Naturopathy / ‘functional medicine’", "Emphasis on time, habits and investigation can prompt useful questions.", "Includes heterogeneous interventions; costly testing, unproven claims or supplements can cause harm.", "Assess each test or treatment separately; no blanket validation of the label.", "Use evidence-backed nutrition or lifestyle elements, if a specific proposal is useful.", "Ask what result changes care and verify the intervention with an independent source.", "https://www.nccih.nih.gov/health/naturopathy"),
    ("🧪 Homeopathy", "Some people value a supportive consultation, but that does not establish remedy efficacy.", "No convincing evidence for treating specific conditions; delay of proven care can be harmful.", "Little evidence of effectiveness for any specific health condition.", "Do not use as treatment for a health condition or a substitute for indicated care.", "Seek an evidence-based assessment; discuss any product or care delay.", "https://www.nccih.nih.gov/health/homeopathy"),
]

def render():
    st.header("🧭 Compare health and wellness approaches")
    st.caption("How to use each approach responsibly · Relevance and evidence depend on the specific condition and intervention")
    st.info("These categories overlap. Preventive care, rehabilitation and psychotherapy are often part of conventional evidence-based care. 'Complementary' means used alongside established care; a label alone does not show benefit.")
    st.dataframe([{"Approach":name,"Potential pros ✅":pros,"Cons / cautions ⚠️":cons,"Evidence snapshot":evidence,"When to consider it":when,"Practical recommendation":action,"Original authority":url} for name,pros,cons,evidence,when,action,url in ROWS],hide_index=True,use_container_width=True,height=610,column_config={"Original authority":st.column_config.LinkColumn("Original authority")})
    st.caption("Swipe or scroll horizontally to see all columns. The evidence snapshot is qualitative and is not a numerical ranking or personal treatment plan.")
    st.subheader("🧩 A quick decision guide")
    need=st.selectbox("What are you trying to address?",["New or worsening symptom","Long-term risk reduction","Function after injury or illness","Stress or mental health concern","Complementary symptom relief","A remedy or supplement claim"],key="approach_need")
    guidance={
        "New or worsening symptom":"Start with a qualified clinician for assessment. Seek urgent services for severe or emergency symptoms.",
        "Long-term risk reduction":"Start with evidence-based prevention: food pattern, activity, sleep and indicated screening or treatment.",
        "Function after injury or illness":"Ask about condition-specific rehabilitation and a measurable function goal.",
        "Stress or mental health concern":"Consider evidence-based psychological care; yoga or meditation may be an adjunct if suitable.",
        "Complementary symptom relief":"Name the exact symptom and practice. Check its evidence and safety with the treating clinician.",
        "A remedy or supplement claim":"Check the exact product, clinical outcome, interaction risk and whether it would delay proven care.",
    }
    st.success(guidance[need])
    st.markdown("**Read first:** [NCCIH on complementary versus integrative care](https://www.nccih.nih.gov/health/complementary-alternative-or-integrative-health-whats-in-a-name) · [NCCIH on safety](https://www.nccih.nih.gov/health/safety) · [CDC on prevention](https://www.cdc.gov/chronic-disease/prevention/index.html)")
